export const importedScreenMap = new Map(importedScreens.map((screen) => [screen.slug, screen]));

export function findImportedScreen(slug: string): ImportedScreen | undefined {
  return importedScreenMap.get(slug);
}

export function getScreenGroups() {
  return importedScreens.reduce<Record<string, ImportedScreen[]>>((acc, screen) => {
    acc[screen.group] ||= [];
    acc[screen.group].push(screen);
    return acc;
  }, {});
}

for (const screen of importedScreens) {
  const localizedTitle = localizedScreenTitles[screen.slug];
  if (localizedTitle) {
    screen.title = localizedTitle;
  }
}
